    material_type := case row_data->>'category' when 'EPI' then 'EPI' when 'EPC' then 'EPC' else 'FERRAMENTAL' end;
    material_category := case row_data->>'category' when 'EPI' then 'EPI' when 'EPC' then 'EPC' when 'ACESS' then 'ACESSORIO' when 'EQUIP' then 'EQUIPAMENTO' when 'TI' then 'TI' else 'FERRAMENTAL' end;
    unit_name := case upper(row_data->>'unit') when 'PAR' then 'PAR' else 'un.' end;
    insert into public.materials (organization_id, internal_code, name, type, unit, ca_number, minimum_stock, status, contract_item_code, contract_item_number, contract_category, usage_scope, contract_source, contract_specification, ca_required, test_required, test_type, test_interval_months, report_required, art_required, notes)
    values (org_id, 'A05-' || lpad((row_data->>'number')::text, 3, '0'), trim(row_data->>'description'), material_type, unit_name, case when material_type = 'EPI' then 'PENDENTE' else null end, 0, 'active', 'A05-' || lpad((row_data->>'number')::text, 3, '0'), (row_data->>'number')::int, material_category, case row_data->>'scope' when 'IND' then 'individual' else 'coletivo' end, 'Contrato WS 93000 - Anexo 05', trim(row_data->>'description'), material_type = 'EPI', material_type in ('EPI','EPC'), case when material_type in ('EPI','EPC') then 'dielectric' else null end, case when material_type in ('EPI','EPC') then 12 else null end, material_type in ('EPI','EPC'), material_type in ('EPI','EPC'), 'Item importado integralmente do Anexo 05. Validar cadastro físico, fabricante, CA e ensaio.')
    on conflict (organization_id, contract_item_code) where contract_item_code is not null do update set name = excluded.name, type = excluded.type, unit = excluded.unit, contract_item_number = excluded.contract_item_number, contract_category = excluded.contract_category, usage_scope = excluded.usage_scope, contract_specification = excluded.contract_specification, ca_required = excluded.ca_required, test_required = excluded.test_required, test_type = excluded.test_type, test_interval_months = excluded.test_interval_months, report_required = excluded.report_required, art_required = excluded.art_required;
    select id into v_material_id from public.materials where organization_id = org_id and contract_item_code = 'A05-' || lpad((row_data->>'number')::text, 3, '0');
    for scenario_code, scenario_index in select * from (values ('LV_DIST_LEVE',1),('LV_DIST_PESADA',2)) as scenarios(code, idx) loop
      quantity_value := coalesce((row_data->'quantities'->>(scenario_index-1))::int, 0);
      if quantity_value > 0 then
        select id into v_scenario_id from public.contract_scenarios where organization_id = org_id and code = scenario_code;
        insert into public.contract_requirements (organization_id, scenario_id, material_id, source_annex, source_item_number, quantity, unit, usage_scope, notes)
        values (org_id, v_scenario_id, v_material_id, 'Anexo 05', (row_data->>'number')::int, quantity_value, unit_name, case row_data->>'scope' when 'IND' then 'individual' else 'coletivo' end, 'Quantidade mínima importada do Anexo 05.')
        on conflict (scenario_id, material_id, usage_scope) do update set quantity = excluded.quantity, unit = excluded.unit, source_item_number = excluded.source_item_number, notes = excluded.notes;
      end if;
    end loop;
  end loop;
end $$;

do $$
declare org_id uuid := '4dc792c1-5087-4eea-a806-e2957cd0d09d'; v_material_id uuid; v_scenario_id uuid;
begin
  insert into public.materials (organization_id, internal_code, name, type, unit, minimum_stock, status, contract_item_code, contract_item_number, contract_category, usage_scope, contract_source, contract_specification, notes)
  values (org_id, 'A05-021', 'Farol SEALED BEAM com lampada BIODO, com tomada de forca no veiculo', 'FERRAMENTAL', 'un.', 0, 'active', 'A05-021', 21, 'ACESSORIO', 'coletivo', 'Contrato WS 93000 - Anexo 05', 'Farol SEALED BEAM com lampada BIODO, com tomada de forca no veiculo', 'Item importado integralmente do Anexo 05.')
  on conflict (organization_id, contract_item_code) where contract_item_code is not null do update set name = excluded.name, contract_specification = excluded.contract_specification;
  insert into public.materials (organization_id, internal_code, name, type, unit, minimum_stock, status, contract_item_code, contract_item_number, contract_category, usage_scope, contract_source, contract_specification, notes)
  values (org_id, 'A05-129', 'Radio Movel Motorola DGM8000 com GPS e componentes', 'FERRAMENTAL', 'un.', 0, 'active', 'A05-129', 129, 'TI', 'coletivo', 'Contrato WS 93000 - Anexo 05', 'Radio Movel Motorola DGM8000 com GPS e componentes', 'Item importado integralmente do Anexo 05.')
  on conflict (organization_id, contract_item_code) where contract_item_code is not null do update set name = excluded.name, contract_specification = excluded.contract_specification;
  for v_material_id, v_scenario_id in select m.id, s.id from public.materials m cross join public.contract_scenarios s where m.organization_id = org_id and s.organization_id = org_id and m.contract_item_code in ('A05-021','A05-129') and s.code in ('LV_DIST_LEVE','LV_DIST_PESADA')
  loop
    insert into public.contract_requirements (organization_id, scenario_id, material_id, source_annex, source_item_number, quantity, unit, usage_scope, notes)
    values (org_id, v_scenario_id, v_material_id, 'Anexo 05', (select contract_item_number from public.materials where id = v_material_id), 1, 'un.', 'coletivo', 'Quantidade minima importada do Anexo 05.')
    on conflict (scenario_id, material_id, usage_scope) do update set quantity = excluded.quantity;
  end loop;
end $$;
